const config=JSON.parse(document.getElementById('site-data').textContent);

// The public cPanel package enables delivery only after the owner verifies its receiving inbox.
if(config.formsHealth){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),5000);fetch(config.formsHealth,{headers:{Accept:'application/json'},cache:'no-store',signal:controller.signal}).then(response=>response.ok?response.json():Promise.reject()).then(result=>{if(!result.delivery_configured)throw Error()}).catch(()=>{document.querySelectorAll('form[data-form]').forEach(form=>{form.dataset.unavailable='true';form.querySelector('[type=submit]').disabled=true;const note=form.querySelector('.form-note')||document.createElement('p'),phone=document.createElement('a');note.className='form-note';note.replaceChildren('Online submissions are temporarily unavailable. ');phone.href='tel:'+config.phone;phone.textContent='Call (213) 720-5588 to speak with our team.';note.append(phone);if(!note.parentNode)form.querySelector('.button-row').before(note)})}).finally(()=>clearTimeout(timer))}
document.querySelectorAll('form[data-form]').forEach(form=>{form.elements.started_at.value=Date.now();form.dataset.loaded=performance.now();let touch={};try{touch=JSON.parse(sessionStorage.getItem('ffa_touch'))||{}}catch{}Object.entries(touch).forEach(([key,value])=>{if(form.elements[key])form.elements[key].value=value});
const sms=form.elements.sms_opt_in,phone=form.elements.phone;if(sms&&phone){sms.addEventListener('change',()=>phone.required=sms.checked)}
form.addEventListener('submit',async e=>{e.preventDefault();const box=form.querySelector('.form-errors'),button=form.querySelector('[type=submit]');box.replaceChildren();box.hidden=true;form.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));button.disabled=true;if(form.elements.fill_ms)form.elements.fill_ms.value=Math.round(performance.now()-Number(form.dataset.loaded||0));
try{if(form.elements.resume?.files?.[0]?.size>5*1024*1024)throw Error('Upload a PDF résumé up to 5 MB.');if(form.dataset.unavailable||!config.formsConfigured)throw Error('Online submissions are temporarily unavailable. Please call (213) 720-5588.');const response=await fetch(form.action,{method:'POST',body:form.enctype==='multipart/form-data'?new FormData(form):new URLSearchParams(new FormData(form)),headers:{Accept:'application/json'}});const result=await response.json();if(!response.ok||!result.ok){if(result.errors&&Object.keys(result.errors).length){Object.entries(result.errors).forEach(([name,message])=>{const field=form.elements[name],p=document.createElement('p'),a=document.createElement('a');a.href='#'+(field?.id||form.id);a.textContent=message;if(field?.setAttribute)field.setAttribute('aria-invalid','true');p.append(a);box.append(p)});throw Error('Please check the highlighted fields.')}throw Error(result.message||(response.status===429?'Please wait a few minutes before trying again.':'Your message could not be sent. Please call (213) 720-5588.'))}const id=form.dataset.form,event={tour_partner:'tour_partner_submit',private_event:'private_event_submit',birthday:'private_event_submit',catering:'catering_submit',press:'press_inquiry_submit',newsletter:'signup'}[id]||'form_submit',count=Number(form.elements.guest_count?.value||form.elements.party_size?.value||form.elements.group_size?.value||0),params={form_id:id,form_location:config.placement||'section'};if(count)params.guest_band=count<=10?'1-10':count<=25?'11-25':count<=50?'26-50':count<=78?'51-78':'79+';for(const key of ['occasion','service_style','group_type'])if(form.elements[key]?.value)params[key]=form.elements[key].value;const source=form.elements.utm_source?.value||'';params.source=/^[a-z_]{1,40}$/.test(source)?source:'(none)';window.dispatchEvent(new CustomEvent('ffa-track',{detail:{event,placement:'section',params}}));const p=document.createElement('p');p.textContent=result.message;box.append(p);form.reset();form.elements.started_at.value=Date.now();form.dataset.loaded=performance.now();}
catch(error){const p=document.createElement('p');p.textContent=(error instanceof TypeError||error instanceof SyntaxError)?'Your message could not be submitted. Please call (213) 720-5588.':error.message;box.prepend(p)}finally{box.hidden=false;box.focus();button.disabled=!!form.dataset.unavailable}})});

document.querySelectorAll('[data-application-role]').forEach(link=>link.addEventListener('click',()=>{const role=document.querySelector('form[data-form="careers"] select[name="role"]');if(role)role.value=link.dataset.applicationRole}));
